// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {SimpleWallet} from "../src/SimpleWallet.sol";

contract InvMutTest is Test {
    SimpleWallet c;
    function setUp() public { c = new SimpleWallet(); }

    // owner of c is this test contract (msg.sender at deploy); allow it to receive ETH
    receive() external payable {}

    function testFuzz_property(uint256 deposit, uint256 w) public {
        vm.assume(deposit > 0);
        vm.assume(w < deposit);
        vm.assume(address(this).balance >= deposit);

        // fund the contract via its payable fallback
        (bool okDeposit, ) = address(c).call{value: deposit}("");
        assertTrue(okDeposit);

        // owner (this contract) withdraws only w
        c.withdraw(w);

        // the contract must retain exactly deposit - w
        assertTrue(address(c).balance == deposit - w);
    }
}
